/* Road-sign drawings for the practice quiz (viewBox 0 0 120 120), after the Indian sign shapes:
   red circles = prohibitions, blue circles = orders, red triangles = warnings, blue rectangles = information. */
(function () {
  const RED = '#C8102E', BLUE = '#1F5FA8', BLK = '#111';
  const svg = inner => `<svg viewBox="0 0 120 120" role="img" aria-hidden="true">${inner}</svg>`;
  const flip = inner => `<g transform="translate(120 0) scale(-1 1)">${inner}</g>`;
  const slash = `<line x1="26" y1="26" x2="94" y2="94" stroke="${RED}" stroke-width="10" stroke-linecap="round"/>`;
  const ring = (inner, sl) => svg(`<circle cx="60" cy="60" r="52" fill="#fff" stroke="${RED}" stroke-width="11"/>${inner}${sl ? slash : ''}`);
  const blueDisc = inner => svg(`<circle cx="60" cy="60" r="56" fill="${BLUE}"/><circle cx="60" cy="60" r="52" fill="none" stroke="#fff" stroke-width="3"/>${inner}`);
  const warn = inner => svg(`<path d="M60 10 L112 102 H8 Z" fill="#fff" stroke="${RED}" stroke-width="10" stroke-linejoin="round"/>${inner}`);
  const info = inner => svg(`<rect x="10" y="10" width="100" height="100" rx="12" fill="${BLUE}"/><rect x="15" y="15" width="90" height="90" rx="9" fill="none" stroke="#fff" stroke-width="3"/>${inner}`);
  const txt = (s, y, size, fill) => `<text x="60" y="${y}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="${size}" fill="${fill}">${s}</text>`;
  const arrowL = c => `<path d="M72 94 V58 H48" fill="none" stroke="${c}" stroke-width="11" stroke-linejoin="round"/><path d="M50 42 V74 L28 58 Z" fill="${c}"/>`;
  const oct = (() => { const p = []; for (let i = 0; i < 8; i++) { const a = Math.PI / 8 + i * Math.PI / 4; p.push((60 + 57 * Math.cos(a)).toFixed(1) + ',' + (60 + 57 * Math.sin(a)).toFixed(1)); } return p.join(' '); })();
  const horn = c => `<rect x="28" y="55" width="30" height="10" rx="3" fill="${c}"/><path d="M56 57 L88 38 Q93 60 88 82 L56 63 Z" fill="${c}"/>`;
  const walker = c => `<circle cx="62" cy="38" r="7" fill="${c}"/><path d="M61 47 L56 68 M56 68 L46 86 M56 68 L68 86 M59 53 L46 62 M59 53 L71 60" stroke="${c}" stroke-width="7" stroke-linecap="round" fill="none"/>`;
  const curveR = `<path d="M54 96 V78 C54 64 58 58 67 53.5" fill="none" stroke="${BLK}" stroke-width="9"/><path d="M80 44 L72.5 61.5 L60.5 46 Z" fill="${BLK}"/>`;
  const light = (lit, flash, arrow) => {
    const C = { red: '#E3262F', amber: '#F5A511', green: '#22A45D' }, off = '#4A4F57';
    const lamp = (k, cy) => `<circle cx="60" cy="${cy}" r="13" fill="${lit === k ? C[k] : off}"/>`;
    const cy = { red: 30, amber: 60, green: 90 }[lit];
    const rays = flash ? [[-30, 0], [30, 0], [-24, -16], [24, -16], [-24, 16], [24, 16]].map(([x, y]) => `<line x1="${60 + x * .75}" y1="${cy + y * .75}" x2="${60 + x}" y2="${cy + y}" stroke="${C[lit]}" stroke-width="4" stroke-linecap="round"/>`).join('') : '';
    const arr = arrow ? `<path d="M52 90 H66" stroke="#23272E" stroke-width="4"/><path d="M64 84 L72 90 L64 96 Z" fill="#23272E"/>` : '';
    return svg(`<rect x="40" y="10" width="40" height="100" rx="9" fill="#23272E"/>${lamp('red', 30)}${lamp('amber', 60)}${lamp('green', 90)}${rays}${arr}`);
  };
  window.SIGNS = {
    stop: svg(`<polygon points="${oct}" fill="${RED}" stroke="#fff" stroke-width="4"/>${txt('STOP', 71, 30, '#fff')}`),
    giveway: svg(`<path d="M10 20 H110 L60 106 Z" fill="#fff" stroke="${RED}" stroke-width="11" stroke-linejoin="round"/>`),
    noentry: svg(`<circle cx="60" cy="60" r="56" fill="${RED}"/><rect x="22" y="50" width="76" height="20" fill="#fff"/>`),
    nohorn: ring(horn(BLK), true),
    noparking: ring(txt('P', 80, 58, BLK), true),
    nostopping: svg(`<circle cx="60" cy="60" r="56" fill="${RED}"/><circle cx="60" cy="60" r="42" fill="${BLUE}"/><path d="M33 33 L87 87 M87 33 L33 87" stroke="${RED}" stroke-width="10" stroke-linecap="round"/>`),
    nouturn: ring(`<path d="M48 92 V52 A14 14 0 0 1 76 52 V64" fill="none" stroke="${BLK}" stroke-width="10"/><path d="M64 62 H88 L76 82 Z" fill="${BLK}"/>`, true),
    noleft: ring(arrowL(BLK), true),
    noright: ring(flip(arrowL(BLK)), true),
    nopedestrians: ring(walker(BLK), true),
    speed50: ring(txt('50', 76, 44, BLK)),
    speed30: ring(txt('30', 76, 44, BLK)),
    restrictionends: svg(`<circle cx="60" cy="60" r="54" fill="#fff" stroke="${BLK}" stroke-width="3"/>${flip(`<path d="M28 36 L36 28 L92 84 L84 92 Z" fill="${BLK}"/>`)}`),
    turnleft: blueDisc(arrowL('#fff')),
    turnright: blueDisc(flip(arrowL('#fff'))),
    keepleft: blueDisc(`<line x1="80" y1="38" x2="50" y2="68" stroke="#fff" stroke-width="11" stroke-linecap="round"/><path d="M34 84 L40 56 L62 78 Z" fill="#fff"/>`),
    ahead: blueDisc(`<line x1="60" y1="94" x2="60" y2="48" stroke="#fff" stroke-width="11"/><path d="M42 52 H78 L60 26 Z" fill="#fff"/>`),
    soundhorn: blueDisc(horn('#fff')),
    crossroad: warn(`<rect x="55" y="44" width="10" height="48" fill="${BLK}"/><rect x="38" y="63" width="44" height="10" fill="${BLK}"/>`),
    tjunction: warn(`<rect x="55" y="62" width="10" height="30" fill="${BLK}"/><rect x="36" y="54" width="48" height="10" fill="${BLK}"/>`),
    sideroadleft: warn(`<rect x="57" y="44" width="10" height="48" fill="${BLK}"/><rect x="38" y="62" width="22" height="10" fill="${BLK}"/>`),
    rightcurve: warn(curveR),
    leftcurve: warn(flip(curveR)),
    narrow: warn(`<path d="M42 96 L50 78 V50 M78 96 L70 78 V50" fill="none" stroke="${BLK}" stroke-width="8" stroke-linejoin="round"/>`),
    hump: warn(`<path d="M26 92 Q60 50 94 92 Z" fill="${BLK}"/>`),
    pedestrian: warn(`<g transform="translate(0 6) scale(1)">${walker(BLK)}</g><g fill="${BLK}">${[32, 44, 56, 68, 80].map(x => `<rect x="${x}" y="93" width="7" height="4"/>`).join('')}</g>`),
    roundabout: warn(`<circle cx="60" cy="72" r="15" fill="none" stroke="${BLK}" stroke-width="6"/>${[0, 120, 240].map(a => `<path d="M60 52 L68 57 L60 62 Z" fill="${BLK}" transform="rotate(${a} 60 72)"/>`).join('')}`),
    parking: info(txt('P', 84, 66, '#fff')),
    petrol: info(`<rect x="38" y="36" width="30" height="52" rx="3" fill="#fff"/><rect x="43" y="42" width="20" height="14" fill="${BLUE}"/><path d="M68 48 H76 V76 Q76 82 82 82 V54" fill="none" stroke="#fff" stroke-width="5"/><rect x="32" y="86" width="42" height="6" fill="#fff"/>`),
    redsteady: light('red', false),
    redflash: light('red', true),
    amberflash: light('amber', true),
    amber: light('amber', false),
    green: light('green', false),
    greenarrow: light('green', false, true)
  };
})();

